const tugas = document.querySelector("#tugas");
const info = document.querySelector("#info");
document.querySelectorAll(".selesai").forEach((li) => li.remove());
const ringkas = document.createElement("strong");
ringkas.textContent = `Sisa ${tugas.children.length} tugas`;
info.replaceWith(ringkas);
console.log(Array.from(tugas.children).map((li) => li.textContent).join(", "));
console.log(document.querySelector("strong").textContent);
